fpath = os.path.join(sessions_dir, "01a188f9-8042-778a-a1fa-0ac8b8755fe7.jsonl")

with open(fpath, 'r') as f:
    content = f.read()

# Look for ALL message types and their content
lines = content.split('\n')
message_types = {}
for line in lines[-100:]:  # Last 100 messages
    try:
        entry = json.loads(line)
        role = entry.get('message', {}).get('role', '')
        msg_type = role

        if msg_type not in message_types:
            message_types[msg_type] = {'count': 0, 'sample': ''}

        message_types[msg_type]['count'] += 1

        text = entry['message'].get('text', '')
        if len(text) > 2000 and '<thinking>' not in text and 'Demo pair' in text.upper():
            message_types[msg_type]['sample'] = text[:500]
    except:
        pass

print("Message type distribution (last 100 lines):")
for t, info in sorted(message_types.items()):
    print(f"  {t}: {info['count']} messages")
    if info['sample']:
        print(f"    Sample contains: Demo pair mentioned")

# Also check if there are any user messages with grid data besides the test input
user_messages_with_grid = 0
for line in lines:
    try:
        entry = json.loads(line)
        role = entry.get('message', {}).get('role', '')
        if role == 'user':
            text = entry['message'].get('text', '')
            if 'grid' in text.lower() and ('input' in text.lower() or 'output' in text.lower()):
                user_messages_with_grid += 1
                snippet = text[text.find("Test input"):text.find("Test input")+500].replace('\\n', '\n')
                print(f"\nUser message with grid data:")
                print(snippet[:400])
    except:
        pass

print(f"\nTotal user messages with 'grid' containing 'input' or 'output': {user_messages_with_grid}")

